What was the soil temperature on Thursday?
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}, scale=0.8]
\draw[->] (0,0)--(0,7.4); \draw[->] (0,0)--(8.5,0); \foreach \y/\lab in {1/4,2/8,3/12,4/16,5/20,6/24} {\draw (-0.15,\y)--(0,\y); \node[left,font=\scriptsize] at (-0.15,\y) {$\lab$};} \node[left,font=\scriptsize] at (-0.15,0) {$0$}; \foreach \x/\lab in {1/Mon,2.4/Tue,3.8/Wed,5.2/Thu,6.6/Fri} {\node[below,font=\scriptsize] at (\x,0) {\lab};}
\draw[thick] (1,3)--(2.4,5)--(3.8,4)--(5.2,6)--(6.6,2); \foreach \p in {(1,3),(2.4,5),(3.8,4),(5.2,6),(6.6,2)} {\fill \p circle (2.5pt);} \node[rotate=90] at (-1.3,3) {Temperature}; \node[below] at (3.8,-1.0) {Day}; \node at (3.8,7.1) {Soil temperature};
\end{tikzpicture}
[/tikz]

When was the insect count lowest?
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}, scale=0.8]
\draw[->] (0,0)--(0,7.4); \draw[->] (0,0)--(8.5,0); \foreach \y/\lab in {1/5,2/10,3/15,4/20,5/25,6/30} {\draw (-0.15,\y)--(0,\y); \node[left,font=\scriptsize] at (-0.15,\y) {$\lab$};} \node[left,font=\scriptsize] at (-0.15,0) {$0$}; \foreach \x/\lab in {1/8am,2.4/9am,3.8/10am,5.2/11am,6.6/12pm} {\node[below,font=\scriptsize] at (\x,0) {\lab};}
\draw[thick] (1,4)--(2.4,2)--(3.8,5)--(5.2,3)--(6.6,6); \foreach \p in {(1,4),(2.4,2),(3.8,5),(5.2,3),(6.6,6)} {\fill \p circle (2.5pt);} \node[rotate=90] at (-1.3,3) {Insects}; \node[below] at (3.8,-1.0) {Time}; \node at (3.8,7.1) {Insects observed};
\end{tikzpicture}
[/tikz]

During which interval did the reading stay unchanged?
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}, scale=0.8]
\draw[->] (0,0)--(0,6.4); \draw[->] (0,0)--(8.5,0); \foreach \y/\lab in {1/10,2/20,3/30,4/40,5/50} {\draw (-0.15,\y)--(0,\y); \node[left,font=\scriptsize] at (-0.15,\y) {$\lab$};} \node[left,font=\scriptsize] at (-0.15,0) {$0$}; \foreach \x/\lab in {1/T1,2.4/T2,3.8/T3,5.2/T4,6.6/T5} {\node[below,font=\scriptsize] at (\x,0) {\lab};}
\draw[thick] (1,2)--(2.4,4)--(3.8,4)--(5.2,5)--(6.6,3); \foreach \p in {(1,2),(2.4,4),(3.8,4),(5.2,5),(6.6,3)} {\fill \p circle (2.5pt);} \node[rotate=90] at (-1.3,2.5) {Reading}; \node[below] at (3.8,-1.0) {Trial}; \node at (3.8,6.1) {Sensor readings};
\end{tikzpicture}
[/tikz]

How much did the snow depth change from Day $2$ to Day $5$?
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}, scale=0.8]
\draw[->] (0,0)--(0,7.4); \draw[->] (0,0)--(8.5,0); \foreach \y/\lab in {1/3,2/6,3/9,4/12,5/15,6/18} {\draw (-0.15,\y)--(0,\y); \node[left,font=\scriptsize] at (-0.15,\y) {$\lab$};} \node[left,font=\scriptsize] at (-0.15,0) {$0$}; \foreach \x/\lab in {1/D1,2.4/D2,3.8/D3,5.2/D4,6.6/D5} {\node[below,font=\scriptsize] at (\x,0) {\lab};}
\draw[thick] (1,2)--(2.4,5)--(3.8,4)--(5.2,6)--(6.6,3); \foreach \p in {(1,2),(2.4,5),(3.8,4),(5.2,6),(6.6,3)} {\fill \p circle (2.5pt);} \node[rotate=90] at (-1.3,3) {Depth (cm)}; \node[below] at (3.8,-1.0) {Day}; \node at (3.8,7.1) {Snow depth};
\end{tikzpicture}
[/tikz]

Which consecutive days had the greatest change in humidity?
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}, scale=0.8]
\draw[->] (0,0)--(0,7.4); \draw[->] (0,0)--(8.5,0); \foreach \y/\lab in {1/10,2/20,3/30,4/40,5/50,6/60} {\draw (-0.15,\y)--(0,\y); \node[left,font=\scriptsize] at (-0.15,\y) {$\lab$};} \node[left,font=\scriptsize] at (-0.15,0) {$0$}; \foreach \x/\lab in {1/Mon,2.4/Tue,3.8/Wed,5.2/Thu,6.6/Fri} {\node[below,font=\scriptsize] at (\x,0) {\lab};}
\draw[thick] (1,5)--(2.4,4)--(3.8,6)--(5.2,2)--(6.6,3); \foreach \p in {(1,5),(2.4,4),(3.8,6),(5.2,2),(6.6,3)} {\fill \p circle (2.5pt);} \node[rotate=90] at (-1.3,3) {Humidity}; \node[below] at (3.8,-1.0) {Day}; \node at (3.8,7.1) {Daily humidity};
\end{tikzpicture}
[/tikz]
